def cost_vs_mid(bids, asks, side, size):
    mid = (bids[0][0] + asks[0][0]) / 2
    levels = asks if side == 'buy' else bids
    left = size
    paid = 0.0
    for price, shares in levels:
        take = min(left, shares)
        paid += take * price
        left -= take
        if left == 0:
            break
    if left > 0:
        raise ValueError('not enough shares in the book')
    if side == 'buy':
        return paid - size * mid
    return size * mid - paid
